      SUBROUTINE RBFGETCC     PARAMETERS FOR FRINGING FIELD OF RBEND AND SBENDCC ----------------------------------------------------------------------      INCLUDE 'DATA2A.CIN'      INCLUDE 'ELM0A.CIN'      INCLUDE 'ELM2A.CIN'      INCLUDE 'ELM2B.CIN'      INCLUDE 'ELM2C.CIN'      INCLUDE 'ELM4A.CIN'      INCLUDE 'ELM15A.CIN'      INCLUDE 'ELM16A.CIN'      INCLUDE 'ELM26B.CIN'      INCLUDE 'INDBND.CIN'      INCLUDE 'INDFF.CIN'      INCLUDE 'INDPAR.CIN'      INCLUDE 'XRAN.CIN'CC     LOCAL VARIABLESC      INTEGER        IADR, IAPB, IBE, ILAYL, IRAB      REAL           DATARC------------------------------------------------------------------------------CC     INDICES FOR PARAMETERSC      NE1 = 12      NE2 = 13      NH1 = 18      NH2 = 19      IF ((BEFORE .AND. NDIF .EQ. 1)     1    .OR. (.NOT. BEFORE .AND. NDIF .NE. 1)) THEN        NBETA = NE1        NRAB = NH1      ELSE IF ((BEFORE .AND. NDIF .NE. 1)     1          .OR. (.NOT. BEFORE .AND. NDIF .EQ. 1)) THEN        NBETA = NE2        NRAB = NH2      ENDIF      NAPB = 22      NLAYL = 23CC     POLE FACE ROTATION ANGLEC      IBE = IPTOJ(NBETA)      IF (IBE .EQ. 0) THEN        IF (TYPE .EQ. 28) BE = 0.5*AL        IF (TYPE .EQ. 29) BE = 0.0        IF (PRAN28(NBETA) .NE. 0.0)     1      BE = BE + PRAN28(NBETA)*XRAN(NBETA)*UNITI(7)      ELSE        IADR = I + IBE        BE = DATAR(IADR)        IF (PRAN28(NBETA) .NE. 0.0)     1      BE = BE + PRAN28(NBETA)*XRAN(NBETA)        BE = BE*UNITI(7)      ENDIF      IF (BEFORE) THEN        BE1 = BE      ELSE        BE2 = BE      ENDIFCC     POLE FACE CURVATUREC      IRAB = IPTOJ(NRAB)      IF (IRAB .NE. 0) THEN        IADR = I + IRAB        RABT = DATAR(IADR)      ENDIF      IF (IRAB .EQ. 0) THEN        IF (BEFORE) THEN          RABT = RAB1I        ELSE          RABT = RAB2I        ENDIF      ENDIF      IF (PRAN28(NRAB) .NE. 0.0)     1    RABT = RABT + PRAN28(NRAB)*XRAN(NRAB)      RABT = RABT/UNITI(8)      IF (BEFORE) THEN        RAB1 = RABT      ELSE        RAB2 = RABT      ENDIFCC     MAGNET APERTUREC      IAPB = IPTOJ(NAPB)      IF (IAPB .EQ. 0) THEN        APB(2) = APBI(2)      ELSE        IADR = I + IAPB        APB(2) = DATAR(IADR)      ENDIF      IF (PRAN28(NAPB) .NE. 0.0)     1    APB(2) = APB(2) + PRAN28(NAPB)*XRAN(NAPB)      APB(2) = APB(2)*UNITI(3)CC     FRINGE FIELD INTEGRALC      LAYK = LAYKIC      ILAYL = IPTOJ(NLAYL)      IF (ILAYL .EQ. 0) THEN        LAYL = LAYLI      ELSE        IADR = I + ILAYL        LAYL = DATAR(IADR)      ENDIF      IF (PRAN28(NLAYL) .NE. 0.0)     1    LAYL = LAYL + PRAN28(NLAYL)*XRAN(NLAYL)C      LAYX = LAYXIC      RETURN      END